#!/bin/bash
#
# Copyright (C) 2026 Intel Corporation
#
# SPDX-License-Identifier: MIT
#
# Splits Go coverage profiles into two:
# a) hand-written code
# b) auto-generated code
#
# Processes all coverage profiles found under the given directory tree.
# Optionally, merges extra coverage data (e.g. from integration tests) into the
# profiles.
#
# Usage: coverage-report.sh <modules-coverage-dir> [<profile-to-merge>]...

set -e -u -o pipefail

GENERATED_MARKER='^// *Code generated by'

if [ $# -lt 1 ]; then
    echo "Usage: ${0##*/} <modules-coverage-dir> [<profile-to-merge>]..."
    exit 1
fi

# The reports are generated in the module directories, hence absolute paths.
MODULES_COVERAGE_DIR=$(realpath "$1")
shift

merge_profiles=$*

generated=$(mktemp)
packages=$(mktemp)
# shellcheck disable=SC2064  # expand the file names now, not on exit
trap "rm -f '${generated}' '${packages}'" EXIT

# Writes the reports of one bucket and prints its total coverage.
report_bucket() {
    local module=$1
    local prefix=$2
    local profile="${prefix}-$3.out"
    local txt_report="${prefix}-$3.txt"
    local html_report="${prefix}-$3.html"

    # Nothing but the mode header: the module has no code of this kind. Drop all
    # artifacts of the bucket so that no stale report of a previous run is left
    # behind.
    if [ ! -s "${profile}" ] || [ "$(wc -l < "${profile}")" -le 1 ]; then
        rm -f "${profile}" "${txt_report}" "${html_report}"
        echo "n/a"
        return
    fi

    go -C "${module}" tool cover -func="${profile}" > "${txt_report}" || return 1
    go -C "${module}" tool cover -html="${profile}" -o "${html_report}" || return 1
    # The last value on the last line of the txt report is the total
    tail -1 "${txt_report}" | awk '{print $NF}'
}

# Prints the blocks belonging to the given module.
filter_module() {
    local module=$1
    shift

    # Pick the ones of this module, by the import path of the package (which does not include nested modules).
    go -C "${module}" list -f '{{.ImportPath}}' ./... > "${packages}"

    awk -F: -v packages="${packages}" '
    BEGIN {
        while ((getline pkg < packages) > 0)
            wanted[pkg] = 1
    }

    # A profile can have only one mode header, the one of the profile merged into.
    /^mode:/ { next }

    # The first field is the file name, its directory is the import path of the package.
    {
        pkg = $1
        sub("/[^/]*$", "", pkg)
        if (pkg in wanted)
            print
    }' "$@"
}

# Reports the coverage of one module.
report_module() {
    local module=$1
    local profile="${MODULES_COVERAGE_DIR}/${module}/coverage.out"
    # Base name of the reports, '<modules-coverage-dir>/<module>/coverage'
    local prefix="${profile%.*}"
    local module_path hand_written_total generated_total

    # The reports are generated from the merged profile, the original is left intact.
    if [ -n "${merge_profiles}" ]; then
        {
            cat "${profile}"
            # shellcheck disable=SC2086  # split the list into arguments
            filter_module "${module}" ${merge_profiles}
        } > "${prefix}-merged.out"
        profile="${prefix}-merged.out"
    fi

    # The file names of a profile are import paths, i.e. the module path followed
    # by the path of the file within the module.
    module_path=$(go -C "${module}" list -m)

    go -C "${module}" tool cover -html="${profile}" -o "${prefix}.html"

    # A module without any generated code makes git-grep fail, any other failure is an error.
    git -C "${module}" grep --no-full-name -l -E "${GENERATED_MARKER}" -- '*.go' |
        sed -e "s|^|${module_path}/|" > "${generated}" || [ $? -eq 1 ]

    # Use ':' as the field separator (no colon in our file names so the first field is the name of the file)
    awk -F: \
        -v generated_list="${generated}" \
        -v hand_written_profile="${prefix}-hand-written.out" \
        -v generated_profile="${prefix}-generated.out" '
    # Read the file that contains the list of generated files, convert to a set, keyed by file name.
    BEGIN {
        while ((getline file < generated_list) > 0)
            generated[file] = 1
    }

    # Both buckets need the mode header of the original profile.
    /^mode:/ {
        print > hand_written_profile
        print > generated_profile
        next
    }

    # Finally, read/split the profile. Write each line of the profile into the corresponding bucket (generated vs. hand-written),
    # depending whether the file name is in the set of generated files.
    {
        profile = ($1 in generated) ? generated_profile : hand_written_profile
        print > profile
    }' "${profile}"

    hand_written_total=$(report_bucket "${module}" "${prefix}" hand-written)
    generated_total=$(report_bucket "${module}" "${prefix}" generated)

    echo "${module_path}: hand-written ${hand_written_total}, generated ${generated_total}"
}

for module in $(find "${MODULES_COVERAGE_DIR}" -name coverage.out -printf '%P\n' | xargs dirname | sort); do
    report_module "${module}"
done | tee "${MODULES_COVERAGE_DIR}/summary.txt"
